use std::path::PathBuf;
use std::process::Command;

#[test]
fn format_workspace_once_then_remove_harness() {
    let status = Command::new("cargo").args(["fmt", "--all"]).status().expect("run cargo fmt");
    assert!(status.success());
    let source = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/format_node_desktop_once.rs");
    std::fs::remove_file(source).expect("remove formatter harness");
}
